r = primitives.call(name='observe_robotwin2_scene', query='handles and poses')
print(r.ok)
o = r.output
try:
    for k in o:
        s = str(o[k])
        print(k, s[:300])
except Exception as e:
    print('err', e, str(o)[:1000])

q = [0.7, 0.0, 0.0, 0.7141]
m = primitives.call(name='measure_robotwin2_actor_visual', actor_label='block1', camera_name='head_camera', depth_scale=1.0, max_points=200)
print('measure', m.ok)
o = m.output
if isinstance(o, dict):
    for k in o:
        print(k, str(o[k])[:200])
else:
    print(str(o)[:500])

for lbl in ['block2','block3']:
    m = primitives.call(name='measure_robotwin2_actor_visual', actor_label=lbl, camera_name='head_camera', depth_scale=1.0, max_points=50)
    print(lbl, m.ok, m.output.get('centroid_pixels'), m.output.get('bbox_pixels'))

pr = primitives.call(name='probe_robotwin2_motion_plan', arm_tag='right', target_pose=[0.1688,0.0114,0.7600]+RP, evidence_handles=H)
print('probe', pr.ok)
o = pr.output
if isinstance(o, dict):
    for k in o:
        if k in ('agent_context','grounding_provenance','diagnostic_evidence'):
            continue
        print(k, str(o[k])[:300])
else:
    print(str(o)[:600])

def block_xyz(name):
    b = primitives.call(name='locate_robotwin2_actor', actor_name=name)
    return [round(v,3) for v in b.output['pose_world'][:3]]

r = primitives.call(name='execute_robotwin2_pick_place', arm_tag='left', source_actor_label='block2', target_actor_label='block1', lift_distance=0.10, pre_grasp_distance=0.08, pre_place_distance=0.08, evidence_handles=H2+H)
print('pickplace', r.ok)
o = r.output
if isinstance(o, dict):
    for k in o:
        if k in ('agent_context','grounding_provenance','diagnostic_evidence','evidence_handles','source_evidence_handles'):
            continue
        print(k, str(o[k])[:200])
print('b1', block_xyz('block1'), 'b2', block_xyz('block2'), 'b3', block_xyz('block3'))
